-- SunSafe Australia: ABS published aggregate data, Tables 1 and 2 only.
-- Source period: November 2023-February 2024. Population: persons aged 15+.
-- Counts are estimates in THOUSANDS, not survey sample counts.
-- Each characteristic is a separate marginal breakdown. Do not sum across
-- characteristics or add Persons to Males/Females. No SA3-level inference.
-- National proportions are source values, never averages of subgroup rates.
-- RSE is percent; margin of error is percentage points, not relative percent.
-- Preserve published values; do not force subgroup totals to reconcile.
-- No product use, brand, ingredient or causal efficacy data in this source.
-- Creates a new database only if absent; inserts only previously absent keys.
IF DB_ID(N'SunSafeAustraliaDW') IS NULL
    EXEC(N'CREATE DATABASE SunSafeAustraliaDW');
GO
USE SunSafeAustraliaDW;
GO
IF SCHEMA_ID(N'stg') IS NULL EXEC(N'CREATE SCHEMA stg');
GO
IF OBJECT_ID(N'stg.ABSProtectionInitial',N'U') IS NULL
CREATE TABLE stg.ABSProtectionInitial (
 Topic nvarchar(80) NOT NULL,
 Breakdown nvarchar(120) NOT NULL,
 Category nvarchar(160) NOT NULL,
 Sex nvarchar(10) NOT NULL,
 EstimateThousands decimal(12,3) NOT NULL,
 EstimateRSEPercent decimal(9,3) NULL,
 ProportionPercent decimal(9,3) NOT NULL,
 MarginOfError95PP decimal(9,3) NULL,
 EstimateSheet nvarchar(20) NOT NULL,
 EstimateCell varchar(12) NOT NULL,
 RSECell varchar(12) NOT NULL,
 ProportionSheet nvarchar(20) NOT NULL,
 ProportionCell varchar(12) NOT NULL,
 MOECell varchar(12) NOT NULL,
 SurveyPeriod varchar(20) NOT NULL DEFAULT '2023-11/2024-02',
 SourceFile nvarchar(100) NOT NULL DEFAULT 'SPBDC01.xlsx',
 CONSTRAINT UQ_ABSProtectionInitial UNIQUE(SurveyPeriod,Topic,Breakdown,Category,Sex)
);
GO
SET XACT_ABORT ON;
